{{ ($('Sourcing Agent').item.json.output.quotes || []).map(q => '• ' + q.species + ' ' + (q.grade || '') + ' ' + (q.form || '') + ': ' + (q.price_per_m3_usd != null ? 'USD ' + q.price_per_m3_usd : 'ZMW ' + q.price_per_m3_zmw) + '/m³, ' + (q.volume_available_m3 ?? '?') + ' m³, ' + (q.lead_time_days ?? '?') + ' days').join('\n') }}
